// Copied by line range from the author's submission for the NVIDIA DLI final
// assessment (maxwell.cu before and after step 2, and coarse.cu). Do not edit
// by hand.
export const CUDA_EXCERPTS = {
  materialized:
    "void update_hx(int n, float dx, float dy, float dt,\n               thrust::device_vector<float> &hx,\n               const thrust::device_vector<float> &ez,\n               thrust::device_vector<float> &buffer) {\n  // Materialize `ez[i + n] - ez[i]` in memory\n  thrust::transform(thrust::device, ez.begin() + n, ez.end(), ez.begin(),\n                    buffer.begin(),\n                    [] __host__ __device__(float x, float y) { return x - y; });\n\n  // Update hx\n  thrust::transform(thrust::device, hx.begin(), hx.end() - n, buffer.begin(),\n                    hx.begin(),\n                    [dt, dx, dy] __host__ __device__(float h, float cex) {\n                      return h - dli::C0 * dt / 1.3f * cex / dy;\n                    });\n}\n",
  fancy:
    "void update_hx(int n, float dx, float dy, float dt,\n               thrust::device_vector<float> &hx,\n               thrust::device_vector<float> &ez) {\n  auto ez_pair = thrust::make_zip_iterator(ez.begin() + n, ez.begin());\n  auto ez_diff = thrust::make_transform_iterator(\n      ez_pair, [] __host__ __device__(const thrust::tuple<float, float> &t) {\n        return thrust::get<0>(t) - thrust::get<1>(t);\n      });\n\n  thrust::transform(thrust::device, hx.begin(), hx.end() - n, ez_diff,\n                    hx.begin(),\n                    [dt, dx, dy] __host__ __device__(float h, float cex) {\n                      return h - dli::C0 * dt / 1.3f * cex / dy;\n                    });\n}\n",
  coarse:
    "__global__ void kernel(dli::temperature_grid_f fine,\n                       dli::temperature_grid_f coarse) {\n  int coarse_row = blockIdx.x / coarse.extent(1);\n  int coarse_col = blockIdx.x % coarse.extent(1);\n  int row = threadIdx.x / dli::tile_size;\n  int col = threadIdx.x % dli::tile_size;\n  int fine_row = coarse_row * dli::tile_size + row;\n  int fine_col = coarse_col * dli::tile_size + col;\n\n  float thread_value = fine(fine_row, fine_col);\n\n  using block_reduce_t = cub::BlockReduce<float, dli::block_threads>;\n  using storage_t = block_reduce_t::TempStorage;\n\n  __shared__ storage_t storage;\n\n  float block_sum = block_reduce_t(storage).Sum(thread_value);\n\n  if (threadIdx.x == 0) {\n    coarse(coarse_row, coarse_col) = block_sum / dli::block_threads;\n  }\n}",
} as const
